// Valida X-Edificia-Auth contra la variable de entorno EDIFICIA_API_SECRET.
// Extrae y expone el body para los nodos siguientes.
const items = $input.all();
const headers = items[0].json.headers;
const expectedSecret = $env.EDIFICIA_API_SECRET;
const receivedSecret = headers['x-edificia-auth'];

if (!expectedSecret) {
  throw new Error('EDIFICIA_API_SECRET environment variable is not configured in n8n.');
}

if (!receivedSecret || receivedSecret !== expectedSecret) {
  return [{ json: { isValid: false } }];
}

const body = items[0].json.body;
return [{ json: { isValid: true, ...body } }];

// Valida que la operación sea GET_TEMPLATE y que storageKey esté presente.
const item = $input.first();
const operation = item.json.operation;
const storageKey = item.json.payload?.storageKey;

if (operation !== 'GET_TEMPLATE') {
  return [{ json: { ...item.json, isValid: false, validationError: 'UNSUPPORTED_OPERATION', validationMessage: 'Este webhook solo acepta GET_TEMPLATE. Use /webhook/template-store para UPLOAD y DELETE.' } }];
}

if (!storageKey || typeof storageKey !== 'string' || storageKey.trim() === '') {
  return [{ json: { ...item.json, isValid: false, validationError: 'REQUEST_INVALID', validationMessage: 'payload.storageKey es obligatorio para GET_TEMPLATE.' } }];
}

return [{ json: { ...item.json, isValid: true } }];

// Comprueba si la descarga fue exitosa y construye la respuesta.
// Si continueOnFail capturó un error de Drive, responde TEMPLATE_NOT_FOUND.
const input = $input.first();
const original = $('Validate GET Request').first().json;
const hasError = !!input.json.error || !input.binary?.data;

if (hasError) {
  return [{
    json: {
      apiVersion: '1.0',
      operation: 'GET_TEMPLATE',
      operationId: original.operationId,
      success: false,
      code: 'TEMPLATE_NOT_FOUND',
      message: 'La plantilla no existe en el almacenamiento',
      provider: 'google-drive',
      timestampUtc: new Date().toISOString(),
      data: null
    },
    _httpStatus: 404
  }];
}

// Encode binary to base64
const binaryData = input.binary.data;
const buffer = await this.helpers.getBinaryDataBuffer(input, 'data');
const contentBase64 = buffer.toString('base64');

return [{
  json: {
    apiVersion: '1.0',
    operation: 'GET_TEMPLATE',
    operationId: original.operationId,
    success: true,
    code: 'TEMPLATE_STORAGE_OK',
    message: 'Plantilla recuperada correctamente',
    provider: 'google-drive',
    timestampUtc: new Date().toISOString(),
    data: {
      storageKey: original.payload.storageKey,
      mimeType: binaryData.mimeType ?? 'application/vnd.openxmlformats-officedocument.wordprocessingml.template',
      fileSizeBytes: binaryData.fileSize ?? null,
      contentBase64
    }
  },
  _httpStatus: 200
}];
